const TEMPLATE_JS = "document.getElementById(\"year\").textContent = new Date().getFullYear();\n\n// Mobile nav toggle\nconst navToggle = document.querySelector(\".nav-toggle\");\nconst mainNav = document.querySelector(\".main-nav\");\nif (navToggle && mainNav) {\n  navToggle.addEventListener(\"click\", () => {\n    const isOpen = mainNav.classList.toggle(\"is-open\");\n    navToggle.setAttribute(\"aria-expanded\", String(isOpen));\n    mainNav.style.display = isOpen ? \"flex\" : \"\";\n    if (isOpen) {\n      mainNav.style.position = \"absolute\";\n      mainNav.style.top = \"76px\";\n      mainNav.style.left = \"0\";\n      mainNav.style.right = \"0\";\n      mainNav.style.flexDirection = \"column\";\n      mainNav.style.padding = \"20px 24px\";\n      mainNav.style.background = \"rgba(5,7,13,0.97)\";\n      mainNav.style.borderBottom = \"1px solid rgba(255,255,255,0.08)\";\n    }\n  });\n  mainNav.querySelectorAll(\"a\").forEach((link) => {\n    link.addEventListener(\"click\", () => {\n      mainNav.classList.remove(\"is-open\");\n      mainNav.removeAttribute(\"style\");\n      navToggle.setAttribute(\"aria-expanded\", \"false\");\n    });\n  });\n}\n\n// Reveal-on-scroll for cards, steps, stats\nconst revealTargets = document.querySelectorAll(\".card, .step, .stat-card, .warum-text, .warum-visual\");\nif (\"IntersectionObserver\" in window) {\n  revealTargets.forEach((el) => {\n    el.style.opacity = \"0\";\n    el.style.transform = \"translateY(18px)\";\n    el.style.transition = \"opacity 0.6s ease, transform 0.6s ease\";\n  });\n  const io = new IntersectionObserver(\n    (entries) => {\n      entries.forEach((entry) => {\n        if (entry.isIntersecting) {\n          entry.target.style.opacity = \"1\";\n          entry.target.style.transform = \"translateY(0)\";\n          io.unobserve(entry.target);\n        }\n      });\n    },\n    { threshold: 0.15 }\n  );\n  revealTargets.forEach((el) => io.observe(el));\n}\n\n// Contact form (no backend yet — opens a pre-filled email as fallback)\nconst CONTACT_EMAIL = \"{{CONTACT_EMAIL}}\";\nconst COMPANY_NAME = \"{{COMPANY_NAME}}\";\n\nconst form = document.getElementById(\"contact-form\");\nconst note = document.getElementById(\"form-note\");\nif (form) {\n  form.addEventListener(\"submit\", (e) => {\n    e.preventDefault();\n    const data = new FormData(form);\n    const name = data.get(\"name\");\n    const email = data.get(\"email\");\n    const message = data.get(\"message\");\n    const subject = encodeURIComponent(`Anfrage über ${COMPANY_NAME}-Website von ${name}`);\n    const body = encodeURIComponent(`${message}\\n\\n— ${name} (${email})`);\n    window.location.href = `mailto:${CONTACT_EMAIL}?subject=${subject}&body=${body}`;\n    note.textContent = \"Ihr E-Mail-Programm wird geöffnet …\";\n  });\n}\n";
